describe('Form Field Labels Accessibility', () => {
  beforeEach(() => {
    cy.visit('/form-page');
  });

  it('should associate labels with form fields using for/id attributes', () => {
    // Verify the form is visible
    cy.get('[data-testid="form-container"]').should('be.visible');

    // Verify email field label is associated with input
    cy.get('[data-testid="email-label"]').should('be.visible');
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="email-label"]').should('have.attr', 'for', 'email-input');

    // Verify password field label is associated with input
    cy.get('[data-testid="password-label"]').should('be.visible');
    cy.get('[data-testid="password-input"]').should('be.visible');
    cy.get('[data-testid="password-label"]').should('have.attr', 'for', 'password-input');

    // Verify name field label is associated with input
    cy.get('[data-testid="name-label"]').should('be.visible');
    cy.get('[data-testid="name-input"]').should('be.visible');
    cy.get('[data-testid="name-label"]').should('have.attr', 'for', 'name-input');

    // Verify form submission button is visible
    cy.get('[data-testid="submit-button"]').should('be.visible');

    // Fill out the form and submit
    cy.get('[data-testid="name-input"]').type('John Doe');
    cy.get('[data-testid="email-input"]').type('john@example.com');
    cy.get('[data-testid="password-input"]').type('Password123');
    cy.get('[data-testid="submit-button"]').click();

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Form submitted successfully');
  });

  it('should handle edge case with empty form fields and associated labels', () => {
    // Verify form is visible
    cy.get('[data-testid="form-container"]').should('be.visible');

    // Verify all labels are present even when fields are empty
    cy.get('[data-testid="email-label"]').should('be.visible');
    cy.get('[data-testid="password-label"]').should('be.visible');
    cy.get('[data-testid="name-label"]').should('be.visible');

    // Verify inputs are empty
    cy.get('[data-testid="email-input"]').should('have.value', '');
    cy.get('[data-testid="password-input"]').should('have.value', '');
    cy.get('[data-testid="name-input"]').should('have.value', '');

    // Attempt to submit empty form
    cy.get('[data-testid="submit-button"]').click();

    // Verify validation error messages appear for each field
    cy.get('[data-testid="email-error"]').should('be.visible');
    cy.get('[data-testid="email-error"]').should('contain', 'Email is required');

    cy.get('[data-testid="password-error"]').should('be.visible');
    cy.get('[data-testid="password-error"]').should('contain', 'Password is required');

    cy.get('[data-testid="name-error"]').should('be.visible');
    cy.get('[data-testid="name-error"]').should('contain', 'Name is required');

    // Verify form is not submitted
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Verify error messages are associated with their respective fields
    cy.get('[data-testid="email-error"]').should('be.visible');
    cy.get('[data-testid="email-input"]').should('have.class', 'input-error');
  });
});
